namespace
{
#if defined(IMF_HAVE_SSE2) && defined(__GNUC__) && !defined(__e2k__)

// Helper functions for gcc + SSE enabled
void
cpuid (int n, int& eax, int& ebx, int& ecx, int& edx)
{
    __asm__ __volatile__ (
        "cpuid"
        : /* Output  */ "=a"(eax), "=b"(ebx), "=c"(ecx), "=d"(edx)
        : /* Input   */ "a"(n)
        : /* Clobber */);
}

#elif defined(_MSC_VER) &&                                                     \
    (defined(_M_IX86) || (defined(_M_AMD64) && !defined(_M_ARM64EC)))

// Helper functions for MSVC
void
cpuid (int n, int& eax, int& ebx, int& ecx, int& edx)
{
    int cpuInfo[4] = {-1};
    __cpuid (cpuInfo, n);
    eax = cpuInfo[0];
    ebx = cpuInfo[1];
    ecx = cpuInfo[2];
    edx = cpuInfo[3];
}

#else // IMF_HAVE_SSE2 && __GNUC__ && !__e2k__

// Helper functions for generic compiler - all disabled
void
cpuid (int n, int& eax, int& ebx, int& ecx, int& edx)
{
    eax = ebx = ecx = edx = 0;
}

#endif // IMF_HAVE_SSE2 && __GNUC__ && !__e2k__

#ifdef IMF_HAVE_GCC_INLINEASM_X86

void
xgetbv (int n, int& eax, int& edx)
{
    __asm__ __volatile__ ("xgetbv"
                          : /* Output  */ "=a"(eax), "=d"(edx)
                          : /* Input   */ "c"(n)
                          : /* Clobber */);
}

#else //  IMF_HAVE_GCC_INLINEASM_X86

void
xgetbv (int n, int& eax, int& edx)
{
    eax = edx = 0;
}

#endif //  IMF_HAVE_GCC_INLINEASM_X86

} // namespace

CpuId::CpuId ()
    : sse2 (false)
    , sse3 (false)
    , ssse3 (false)
    , sse4_1 (false)
    , sse4_2 (false)
    , avx (false)
    , f16c (false)
{
#if defined(__e2k__) // e2k - MCST Elbrus 2000 architecture
    // Use IMF_HAVE definitions to determine e2k CPU features
#    if defined(IMF_HAVE_SSE2)
    sse2 = true;
#    endif
#    if defined(IMF_HAVE_SSE3)
    sse3 = true;
#    endif
#    if defined(IMF_HAVE_SSSE3)
