#    endif
#    if defined(IMF_HAVE_SSE4_1)
    sse4_1 = true;
#    endif
#    if defined(IMF_HAVE_SSE4_2)
    sse4_2 = true;
#    endif
#    if defined(IMF_HAVE_AVX)
    avx = true;
#    endif
#    if defined(IMF_HAVE_F16C)
    f16c = true;
#    endif
#else // x86/x86_64
    bool osxsave = false;
    int  max     = 0;
    int  eax, ebx, ecx, edx;

    cpuid (0, max, ebx, ecx, edx);
    if (max > 0)
    {
        cpuid (1, eax, ebx, ecx, edx);
        sse2    = (edx & (1 << 26));
