36: 
37: namespace FpuControl
38: {
39: 
40: //-------------------------------------------------------------------
41: //
42: //    Modern x86 processors and all AMD64 processors have two
43: //    sets of floating-point control/status registers: cw and sw
44: //    for legacy x87 stack-based arithmetic, and mxcsr for
45: //    SIMD arithmetic.  When setting exception masks or checking
46: //    for exceptions, we must set/check all relevant registers,
47: //    since applications may contain code that uses either FP
48: //    model.
49: //
50: //    These functions handle both FP models for x86 and AMD64.
51: //
52: //-------------------------------------------------------------------
53: 
54: //-------------------------------------------------------------------
55: //
56: //    Restore the control register state from a signal handler
57: //    user context, optionally clearing the exception bits
58: //    in the restored control register, if applicable.
59: //
60: //-------------------------------------------------------------------
61: 
62: void restoreControlRegs (const ucontext_t& ucon, bool clearExceptions = false);
63: 
64: //------------------------------------------------------------
65: //
66: //    Set exception mask bits in the control register state.
67: //    A value of 1 means the exception is masked, a value of
68: //    0 means the exception is enabled.
69: //
70: //    setExceptionMask returns the previous mask value.  If
71: //    the 'exceptions' pointer is non-null, it returns in
72: //    this argument the FPU exception bits.
73: //
74: //------------------------------------------------------------
75: 
76: const int INVALID_EXC   = (1 << 0);
77: const int DENORMAL_EXC  = (1 << 1);
78: const int DIVZERO_EXC   = (1 << 2);
79: const int OVERFLOW_EXC  = (1 << 3);
80: const int UNDERFLOW_EXC = (1 << 4);
81: const int INEXACT_EXC   = (1 << 5);
82: const int ALL_EXC = INVALID_EXC | DENORMAL_EXC | DIVZERO_EXC | OVERFLOW_EXC |
83:                     UNDERFLOW_EXC | INEXACT_EXC;
84: 
85: int setExceptionMask (int mask, int* exceptions = 0);
86: int getExceptionMask ();
87: 
88: //---------------------------------------------
89: //
90: //    Get/clear the exception bits in the FPU.
91: //
92: //---------------------------------------------
93: 
94: int  getExceptions ();
95: void clearExceptions ();
96: 
97: //------------------------------------------------------------------
98: //
99: //    Everything below here is implementation.  Do not use these
100: //    constants or functions in your applications or libraries.
101: //    This is not the code you're looking for.  Move along.
102: //
103: //    Optimization notes -- on a Pentium 4, at least, it appears
104: //    to be faster to get the mxcsr first and then the cw; and to
105: //    set the cw first and then the mxcsr.  Also, it seems to
106: //    be faster to clear the sw exception bits after setting
107: //    cw and mxcsr.
108: //
109: //------------------------------------------------------------------
110: 
111: static inline uint16_t
112: getSw ()
113: {
114:     uint16_t sw;
115:     asm volatile ("fnstsw %0" : "=m"(sw) :);
116:     return sw;
117: }
118: 
119: static inline void
120: setCw (uint16_t cw)
121: {
122:     asm volatile ("fldcw %0" : : "m"(cw));
123: }
124: 
125: static inline uint16_t
126: getCw ()
127: {
128:     uint16_t cw;
129:     asm volatile ("fnstcw %0" : "=m"(cw) :);
130:     return cw;
131: }
132: 
133: static inline void
134: setMxcsr (uint32_t mxcsr, bool clearExceptions)
135: {
136:     mxcsr &= clearExceptions ? 0xffffffc0 : 0xffffffff;
137:     asm volatile ("ldmxcsr %0" : : "m"(mxcsr));
138: }
139: 
140: static inline uint32_t
141: getMxcsr ()
142: {
143:     uint32_t mxcsr;
144:     asm volatile ("stmxcsr %0" : "=m"(mxcsr) :);
145:     return mxcsr;
146: }
147: 
148: static inline int
149: calcMask (uint16_t cw, uint32_t mxcsr)
150: {
151:     //
152:     // Hopefully, if the user has been using FpuControl functions,
153:     // the masks are the same, but just in case they're not, we
154:     // AND them together to report the proper subset of the masks.
155:     //
156: 
157:     return (cw & ALL_EXC) & ((mxcsr >> 7) & ALL_EXC);
158: }
159: 
160: inline int
161: setExceptionMask (int mask, int* exceptions)
162: {
163:     uint16_t cw    = getCw ();
164:     uint32_t mxcsr = getMxcsr ();
165: 
166:     if (exceptions) *exceptions = (mxcsr & ALL_EXC) | (getSw () & ALL_EXC);
167: 
168:     int oldmask = calcMask (cw, mxcsr);
169: 
170:     //
171:     // The exception constants are chosen very carefully so that
172:     // we can do a simple mask and shift operation to insert
173:     // them into the control words.  The mask operation is for
174:     // safety, in case the user accidentally set some other
175:     // bits in the exception mask.
176:     //
177: 
178:     mask &= ALL_EXC;
179:     cw    = (cw & ~ALL_EXC) | mask;
180:     mxcsr = (mxcsr & ~(ALL_EXC << 7)) | (mask << 7);
181: 
182:     setCw (cw);
183:     setMxcsr (mxcsr, false);
184: 
185:     return oldmask;
186: }
187: 
188: inline int
189: getExceptionMask ()
190: {
191:     uint32_t mxcsr = getMxcsr ();
192:     uint16_t cw    = getCw ();
193:     return calcMask (cw, mxcsr);
194: }
195: 
196: inline int
197: getExceptions ()
198: {
199:     return (getMxcsr () | getSw ()) & ALL_EXC;
200: }
201: 
202: void
203: clearExceptions ()
204: {
205:     uint32_t mxcsr = getMxcsr () & 0xffffffc0;
206:     asm volatile ("ldmxcsr %0\n"
207:                   "fnclex"
208:                   :
209:                   : "m"(mxcsr));
210: }
211: 
212: // If the fpe was taken while doing a float-to-int cast using the x87,
213: // the rounding mode and possibly the precision will be wrong.  So instead
214: // of restoring to the state as of the fault, we force the rounding mode
215: // to be 'nearest' and the precision to be double extended.
216: //
217: // rounding mode is in bits 10-11, value 00 == round to nearest
218: // precision is in bits 8-9, value 11 == double extended (80-bit)
219: //
220: const uint16_t cwRestoreMask = ~((3 << 10) | (3 << 8));
221: const uint16_t cwRestoreVal  = (0 << 10) | (3 << 8);
222: 
223: #    ifdef IEX_HAVE_CONTROL_REGISTER_SUPPORT
224: 
225: inline void
226: restoreControlRegs (const ucontext_t& ucon, bool clearExceptions)
227: {
228:     setCw ((ucon.uc_mcontext.fpregs->cwd & cwRestoreMask) | cwRestoreVal);
229:     setMxcsr (ucon.uc_mcontext.fpregs->mxcsr, clearExceptions);
230: }
231: 
232: #    else
233: 
234: //
235: // Ugly, the mxcsr isn't defined in GNU libc ucontext_t, but
236: // it's passed to the signal handler by the kernel.  Use
237: // the kernel's version of the ucontext to get it, see
238: // <asm/sigcontext.h>
239: //
240: 
241: #        include <asm/sigcontext.h>
242: 
243: inline void
244: restoreControlRegs (const ucontext_t& ucon, bool clearExceptions)
245: {
246: #        if (defined(__linux__) && defined(__i386__)) ||                       \
247:             defined(__ANDROID_API__)
248:     setCw ((ucon.uc_mcontext.fpregs->cw & cwRestoreMask) | cwRestoreVal);
249: #        else
250:     setCw ((ucon.uc_mcontext.fpregs->cwd & cwRestoreMask) | cwRestoreVal);
251: #        endif
252: 
253:     _fpstate* kfp = reinterpret_cast<_fpstate*> (ucon.uc_mcontext.fpregs);
254: #        if defined(__linux__) && defined(__i386__)
255:     setMxcsr (kfp->magic == 0 ? kfp->mxcsr : 0, clearExceptions);
256: #        else
257:     setMxcsr (kfp->mxcsr, clearExceptions);
258: #        endif
259: }
260: 
261: #    endif
262: 
263: } // namespace FpuControl
264: 
265: namespace
266: {
267: 
268: volatile FpExceptionHandler fpeHandler = 0;
269: 
270: extern "C" void
271: catchSigFpe (int sig, siginfo_t* info, ucontext_t* ucon)
272: {
273:     debug ("catchSigFpe (sig = " << sig << ", ...)\n");
274: 
275:     FpuControl::restoreControlRegs (*ucon, true);
276: 
277:     if (fpeHandler == 0) return;
278: 
279:     if (info->si_code == SI_USER)
280:     {
281:         fpeHandler (
282:             0,
283:             "Floating-point exception, caused by "
284:             "a signal sent from another process.");
285:         return;
286:     }
287: 
288:     if (sig == SIGFPE)
289:     {
290:         switch (info->si_code)
291:         {
292:                 //
293:                 // IEEE 754 floating point exceptions:
294:                 //
295: 
296:             case FPE_FLTDIV:
297:                 fpeHandler (IEEE_DIVZERO, "Floating-point division by zero.");
298:                 return;
299: 
300:             case FPE_FLTOVF:
301:                 fpeHandler (IEEE_OVERFLOW, "Floating-point overflow.");
302:                 return;
303: 
304:             case FPE_FLTUND:
305:                 fpeHandler (IEEE_UNDERFLOW, "Floating-point underflow.");
306:                 return;
307: 
308:             case FPE_FLTRES:
309:                 fpeHandler (IEEE_INEXACT, "Inexact floating-point result.");
310:                 return;
311: 
312:             case FPE_FLTINV:
313:                 fpeHandler (IEEE_INVALID, "Invalid floating-point operation.");
314:                 return;
315: 
316:                 //
317:                 // Other arithmetic exceptions which can also
318:                 // be trapped by the operating system:
319:                 //
320: 
321:             case FPE_INTDIV: fpeHandler (0, "Integer division by zero."); break;
322: 
323:             case FPE_INTOVF: fpeHandler (0, "Integer overflow."); break;
324: 
325:             case FPE_FLTSUB: fpeHandler (0, "Subscript out of range."); break;
326:         }
327:     }
328: 
329:     fpeHandler (0, "Floating-point exception.");
330: }
331: 
332: } // namespace
333: 
334: void
335: setFpExceptions (int when)
336: {
337:     int mask = FpuControl::ALL_EXC;
338: 
339:     if (when & IEEE_OVERFLOW) mask &= ~FpuControl::OVERFLOW_EXC;
340:     if (when & IEEE_UNDERFLOW) mask &= ~FpuControl::UNDERFLOW_EXC;
341:     if (when & IEEE_DIVZERO) mask &= ~FpuControl::DIVZERO_EXC;
342:     if (when & IEEE_INEXACT) mask &= ~FpuControl::INEXACT_EXC;
343:     if (when & IEEE_INVALID) mask &= ~FpuControl::INVALID_EXC;
344: 
345:     //
346:     // The Linux kernel apparently sometimes passes
347:     // incorrect si_info to signal handlers unless
348:     // the exception flags are cleared.
349:     //
350:     // XXX is this still true on 2.4+ kernels?
351:     //
352: 
353:     FpuControl::setExceptionMask (mask);
354:     FpuControl::clearExceptions ();
355: }
356: 
357: int
358: fpExceptions ()
359: {
360:     int mask = FpuControl::getExceptionMask ();
361: 
362:     int when = 0;
363: 
364:     if (!(mask & FpuControl::OVERFLOW_EXC)) when |= IEEE_OVERFLOW;
365:     if (!(mask & FpuControl::UNDERFLOW_EXC)) when |= IEEE_UNDERFLOW;
366:     if (!(mask & FpuControl::DIVZERO_EXC)) when |= IEEE_DIVZERO;
367:     if (!(mask & FpuControl::INEXACT_EXC)) when |= IEEE_INEXACT;
368:     if (!(mask & FpuControl::INVALID_EXC)) when |= IEEE_INVALID;
369: 
370:     return when;
371: }
372: 
373: void
374: handleExceptionsSetInRegisters ()
375: {
376:     if (fpeHandler == 0) return;
377: 
378:     int mask = FpuControl::getExceptionMask ();
379: 
380:     int exc = FpuControl::getExceptions ();
381: 
382:     if (!(mask & FpuControl::DIVZERO_EXC) && (exc & FpuControl::DIVZERO_EXC))
383:     {
384:         fpeHandler (IEEE_DIVZERO, "Floating-point division by zero.");
385:         return;
386:     }
387: 
388:     if (!(mask & FpuControl::OVERFLOW_EXC) && (exc & FpuControl::OVERFLOW_EXC))
389:     {
390:         fpeHandler (IEEE_OVERFLOW, "Floating-point overflow.");
391:         return;
392:     }
393: 
394:     if (!(mask & FpuControl::UNDERFLOW_EXC) &&
