#ifndef INCLUDED_IMF_COMPILER_SPECIFIC_H
#define INCLUDED_IMF_COMPILER_SPECIFIC_H

#include "ImfExport.h"
#include "ImfNamespace.h"
#include "ImfSimd.h"
